    dict(k=70, n="Sourozenci Františka Löwa (Praha, sv. Vojtěch)", t="Děti Antonína Lewa (Löwa) podle rejstříku narozených sv. Vojtěcha (Nové Město pražské): Kateřina 1. 11. 1796, Marie Magdalena (?) 11. 8. 1798, František 24. 7. 1800 (asi zemřel – jméno dostal i další syn), Josef 9. 12. 1801, František 5. 12. 1803 (náš), Antonín 14. 4. 1806 († 18. 12. 1809 na neštovice), Jan 29. 8. 1808 († 7. 1. 1810 na křeče) – oba zemřeli v domě č. 415 „U pěti králů“ Na hrobci (Podskalí). Rodiče se tedy brali asi 1795–96 – u sv. Vojtěcha sňatek není (ani u sv. Jindřicha, sv. Petra, v Týně, u P. Marie Vítězné a sv. Štěpána 1788–1796).", r=[]),
    dict(k=17, n="Josef František Karel Linek (* 1853)", t="Starší bratr Marie. Nar. 15. 11. 1853 ve mlýně ve Smetanově Lhotě č. 68 (fara Čimelice); kmotry byli dědeček a babička Löwovi z Drhovle. Křestní list mu vydali 1862.", r=["n_1853_linek_josef"]),
    dict(k=17, n="František Pavel Hynek Karel Linek (* 1855)", t="Starší bratr Marie. Nar. v létě 1855 ve mlýně ve Smetanově Lhotě č. 68 (fara Čimelice).", r=["n_1855_linek_frantisek"]),
    dict(k=256, n="Johanna z Gillernů († 1782)", t="Manželka Maximiliána svobodného pána z Gillernů („Conthoralis Perill. D. Maximiliani Venatorum Supremi Praefecti“), † 18. 2. 1782 Poděbrady, 59 let (* asi 1723), pohřbena u sv. Kříže. Doložena po jeho boku od roku 1750 (Bor Bobnický „Anna Johanna“ / „Maria Johanna“, Hradištko 1756, Kladruby 1757–1761, Čelákovice 1764–1766) jako matka devíti dětí. Josefovou matkou mohla být jen tehdy, pokud se Josef narodil asi 1746/47 (52 let při úmrtí); při narození asi 1738 (48 let při sňatku) to byla nejspíš Maximiliánova druhá manželka – nerozhodnuto. Rodné příjmení neznámé.", r=["z_1782_gillern_johanna", "n_1750_giller_anna_alexia", "n_1756_giller_marie_terezie", "n_1766_gillern_jan_bedrich"]),
    dict(k=256, n="Jan Bedřich (Friedrich) baron z Gillernů, kapitán", t="Blízký příbuzný Maximiliána (bratr, bratranec nebo synovec – zatím nevíme). Kapitán císařského pěšího pluku hraběte Pallaviciniho. 1761 svědek (v zastoupení) při křtu Maximiliánova syna v Kladrubech; × 17. 2. 1765 Pardubice Anna, dcera měšťana Josefa Nešky (?); 5. 2. 1765 (12 dní před svatbou) svědek při křtu v Pardubicích spolu s nevěstou Annou. 1766 svědek při křtu Maximiliánova syna Jana Bedřicha v Čelákovicích (chlapec dostal jeho jméno). Děti ani úmrtí v Pardubicích (1765–1810) nenalezeny – pluk nejspíš odešel jinam. Annin otec je asi pardubický měšťan Josef Neska, † 17. 11. 1769, 69 let.", r=["o_1765_gyller_bedrich", "n_1761_gillern_jan_baptista", "n_1766_gillern_jan_bedrich"]),
